  apps['mei-clicker']={title:'Мей-Мей кликер',icon:'🐆',html:'<div class="mei-clicker-head"><p>Тапай по Мей-Мей, собирай коины и открывай улучшения ❄️</p><div class="mei-clicker-balance"><span>Баланс</span><strong id="mei-clicker-coins">0</strong><small>снежных коинов</small></div></div><section class="mei-clicker-level"><div><strong id="mei-clicker-level">Уровень 1</strong><span id="mei-clicker-xp">0 / 120 XP</span></div><div class="mei-clicker-progress"><i id="mei-clicker-progress"></i></div></section><button class="mei-clicker-tap" id="mei-clicker-tap" type="button" aria-label="Нажать на Мей-Мей"><img src="mini-mei-holiday.png" alt="Мей-Мей в новогодней шапке"><span>+<b id="mei-clicker-power">1</b></span></button><div class="mei-clicker-stats"><div><strong id="mei-clicker-taps">0</strong><span>тапов</span></div><div><strong id="mei-clicker-rate">0</strong><span>коинов / сек</span></div><div><strong id="mei-clicker-crit">4%</strong><span>шанс крита</span></div></div><p class="mei-clicker-status" id="mei-clicker-status" aria-live="polite">Нажми на Мей-Мей — она готова к сбору коинов 🐾</p><section class="mei-clicker-upgrades"><h3>Мастерская лапки</h3><article class="mei-clicker-upgrade"><div><strong>Сильная лапка</strong><span id="mei-clicker-effect-tap">Больше коинов за каждый тап</span></div><button class="mini-secondary" type="button" data-clicker-upgrade="tap">Улучшить · <span id="mei-clicker-price-tap">150</span> 🪙</button></article><article class="mei-clicker-upgrade"><div><strong>Снежный помощник</strong><span id="mei-clicker-effect-auto">Даёт коины каждую секунду</span></div><button class="mini-secondary" type="button" data-clicker-upgrade="auto">Нанять · <span id="mei-clicker-price-auto">500</span> 🪙</button></article><article class="mei-clicker-upgrade"><div><strong>Удача Мей-Мей</strong><span id="mei-clicker-effect-crit">Повышает шанс критического тапа ×4</span></div><button class="mini-secondary" type="button" data-clicker-upgrade="crit">Улучшить · <span id="mei-clicker-price-crit">900</span> 🪙</button></article></section><p class="mini-privacy">Коины игровые и хранятся только на этом устройстве. Автосбор офлайн ограничен восемью часами.</p>'};
  apps['mei-market']={title:'Биржа Мей-Мей',icon:'📈',html:`<section class="mei-market" aria-labelledby="mei-market-heading"><header class="mei-market-heading"><div><span class="mei-market-kicker">ОБЩИЙ РЫНОК · ДЕМО</span><h3 id="mei-market-heading">Акции Мей-Мей</h3></div><span class="mei-market-live"><i></i> ОНЛАЙН</span></header><p class="mei-market-intro">Один курс для всех посетителей: покупки двигают его вверх, продажи — вниз.</p><div class="mei-market-quote"><span>Текущий курс</span><strong id="mei-market-price">— ₽</strong><span id="mei-market-change" class="mei-market-change">Подключаемся к рынку…</span></div><div class="mei-market-chart"><svg viewBox="0 0 600 180" role="img" aria-label="График общего курса акций"><path class="mei-market-chart-grid" d="M0 30H600M0 90H600M0 150H600"/><polyline id="mei-market-line" points="0,90 600,90"/><circle id="mei-market-dot" cx="600" cy="90" r="7"/></svg></div><div class="mei-market-trade"><label for="mei-market-quantity">Количество виртуальных акций</label><select id="mei-market-quantity" class="mini-gift-select"><option value="1">1 акция</option><option value="2">2 акции</option><option value="3">3 акции</option><option value="4">4 акции</option><option value="5">5 акций</option></select><div class="mei-market-actions"><button class="mei-market-buy" id="mei-market-buy" type="button">Купить · поднять курс ↗</button><button class="mei-market-sell" id="mei-market-sell" type="button">Продать · понизить курс ↘</button></div></div><p class="mini-output mei-market-status" id="mei-market-status" aria-live="polite">Загружаем общий курс…</p><p class="mini-privacy">Игровая симуляция: без реальных денег, владения акциями и финансовых операций. Все видят одну серверную котировку; она обновляется автоматически.</p></section>`};
  const meiTips={assistant:'Помогу подготовить открытку к отправке 🎄',lamp:'Добавим немного света и уюта ✨',habits:'Маленький шаг — и привычка крепче 🌱',telegram:'Помогу найти нужный бот ➤',snowcatch:'Лови снежинки, я болею за тебя ❄',focus:'Пора спокойно сосредоточиться ⏳',checklist:'Разберём дела по одному ✓',mood:'Как ты сегодня? Я рядом ☺',countdown:'До праздника уже совсем немного 🎄',password:'Пусть пароль будет надёжным 🔐',calculator:'Сейчас всё точно посчитаем ✨',texttools:'Приведём текст в порядок Aa',converter:'Переведём всё без путаницы ↔',notes:'Запиши идею, чтобы не потерять ✍',budget:'Следим за расходами бережно ₽',casino:'Крутим фрукты и собираем коллекцию 🍎',stream:'Включу уютный эфир прямо поверх сайта 📺','mei-clicker':'Жми на лапку — собирай коины 🐾','mei-market':'Каждый гость может пошевелить общий курс 📈'};
  const escapeHTML=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const storeKeys={habits:'frokla.habits.v1',checklist:'frokla.checklist.v1',mood:'frokla.mood.v1',notes:'frokla.notes.v1',budget:'frokla.budget.v1',casino:'frokla.casino.v1',clicker:'frokla.mei-clicker.v1'};
  const menu=document.getElementById('mini-service-menu');
  let gameTimer=0,moveTimer=0,gameScore=0,gameTime=20,serviceTimers=[],focusTimer=0,focusSeconds=1500,focusRunning=false,streamNode=null,streamTimer=0,casinoState=null,clickerState=null,clickerTimer=0,marketLoading=false,marketSubmitting=false;
  function clearActivities(){stopGame();serviceTimers.forEach(timer=>{clearInterval(timer);clearTimeout(timer)});serviceTimers=[];clickerTimer=0;clearInterval(focusTimer);focusTimer=0;focusRunning=false}
  function addInterval(fn,ms){const timer=setInterval(fn,ms);serviceTimers.push(timer);return timer}
  const marketNumber=new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0});
  function renderMarket(snapshot){
    const price=document.getElementById('mei-market-price'),change=document.getElementById('mei-market-change'),line=document.getElementById('mei-market-line'),dot=document.getElementById('mei-market-dot');if(!price||!change)return;
    const current=Number(snapshot.price)||1000,opening=Number(snapshot.openingPrice)||1000,percent=(current-opening)/opening*100;
    price.textContent=marketNumber.format(current)+' ₽';change.className='mei-market-change '+(percent>0?'is-up':percent<0?'is-down':'');change.textContent=(percent>0?'+':'')+percent.toFixed(2).replace('.',',')+'% с начала · общий курс';
    const values=[opening,...(Array.isArray(snapshot.ticks)?snapshot.ticks.slice().reverse().map(tick=>Number(tick.price)).filter(Number.isFinite):[])];if(values.at(-1)!==current)values.push(current);const visible=values.slice(-30),min=Math.min(...visible),max=Math.max(...visible),span=Math.max(1,max-min),points=visible.map((value,index)=>`${Math.round(index/(visible.length-1||1)*600)},${Math.round(160-(value-min)/span*140)}`).join(' ');if(line)line.setAttribute('points',points);if(dot){const last=points.split(' ').at(-1).split(',');dot.setAttribute('cx',last[0]);dot.setAttribute('cy',last[1])}
  }
  async function loadMarket(){if(marketLoading||!document.getElementById('mei-market-status'))return;marketLoading=true;try{const response=await window.froklaRequest('/api/mei-market',{cache:'no-store'}),data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'Не удалось загрузить общий курс.');renderMarket(data);const status=document.getElementById('mei-market-status');if(status)status.textContent='Котировка общая для всех посетителей · обновляется каждые 5 секунд.'}catch(error){const status=document.getElementById('mei-market-status');if(status)status.textContent=window.froklaLocal?'Общий рынок доступен при запуске через Rust-сервер (cargo run --release).':error.message||'Не удалось связаться с сервером рынка.'}finally{marketLoading=false}}
