  function ensureClicker(){if(!clickerState){const saved=readStored(storeKeys.clicker,null);clickerState=saved&&typeof saved==='object'?saved:{coins:0,tapPower:1,power:1,taps:0}}const state=clickerState;state.coins=Number.isSafeInteger(state.coins)&&state.coins>=0?state.coins:0;state.taps=Number.isSafeInteger(state.taps)&&state.taps>=0?state.taps:0;state.tapPower=Number.isSafeInteger(state.tapPower)&&state.tapPower>0?state.tapPower:(Number.isSafeInteger(state.power)&&state.power>0?state.power:1);state.tapLevel=Number.isSafeInteger(state.tapLevel)&&state.tapLevel>=0?state.tapLevel:Math.max(0,state.tapPower-1);state.autoLevel=Number.isSafeInteger(state.autoLevel)&&state.autoLevel>=0?state.autoLevel:0;state.critLevel=Number.isSafeInteger(state.critLevel)&&state.critLevel>=0?state.critLevel:0;state.xp=Number.isSafeInteger(state.xp)&&state.xp>=0?state.xp:0;state.level=Number.isSafeInteger(state.level)&&state.level>0?state.level:1;state.lifetimeCoins=Number.isSafeInteger(state.lifetimeCoins)&&state.lifetimeCoins>=0?state.lifetimeCoins:state.coins;state.combo=Number.isSafeInteger(state.combo)&&state.combo>0?Math.min(25,state.combo):0;state.lastTapAt=Number.isFinite(state.lastTapAt)?state.lastTapAt:0;state.lastTick=Number.isFinite(state.lastTick)?state.lastTick:Date.now();return state}
